from fastapi import Depends, HTTPException
from typing import List, Optional
from ..middleware.auth_middleware import get_current_user
from ..core.exceptions import ForbiddenException


class CurrentUser:
    """Represents the authenticated user injected into requests."""

    def __init__(
        self,
        id: str,
        email: str,
        full_name: str,
        role: str,
        roles: List[str],
        primary_role: str,
        is_active: bool = True,
        is_admin_approved: bool = False,
        is_verified: bool = False,
    ):
        self.id = id
        self.email = email
        self.full_name = full_name
        self.role = role
        self.roles = roles
        self.primary_role = primary_role
        self.is_active = is_active
        self.is_admin_approved = is_admin_approved
        self.is_verified = is_verified

    def has_role(self, role: str) -> bool:
        return role in self.roles

    def has_any_role(self, roles: List[str]) -> bool:
        return bool(set(self.roles) & set(roles))

    @property
    def is_admin(self) -> bool:
        return self.has_any_role(["super_admin", "admin"])

    @property
    def is_doctor(self) -> bool:
        return self.has_role("doctor")

    @property
    def is_patient(self) -> bool:
        return self.has_any_role(["patient", "client"])

    @property
    def is_hospital(self) -> bool:
        return self.has_any_role(["hospital", "hospital_admin"])

    @property
    def is_pharmacy(self) -> bool:
        return self.has_any_role(["pharmacy", "pharmacy_admin"])

    @property
    def is_blood_donor(self) -> bool:
        return self.has_role("blood_donor")


def require_role(*allowed_roles: str):
    """
    FastAPI dependency that enforces role-based access control.
    Usage: @router.get("/", dependencies=[Depends(require_role("admin", "super_admin"))])
    """
    async def role_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_active:
            raise ForbiddenException("Account is deactivated")
        if not current_user.has_any_role(list(allowed_roles)):
            raise ForbiddenException(
                f"Access denied. Required role: {', '.join(allowed_roles)}"
            )
        return current_user

    return role_checker


def require_admin():
    """Shortcut for admin-only endpoints."""
    return require_role("super_admin", "admin")


def require_doctor():
    """Shortcut for doctor-only endpoints."""
    return require_role("doctor")


def require_patient():
    """Shortcut for patient/client endpoints."""
    return require_role("patient", "client")


def require_hospital():
    """Shortcut for hospital endpoints."""
    return require_role("hospital", "hospital_admin")


def require_pharmacy():
    """Shortcut for pharmacy endpoints."""
    return require_role("pharmacy", "pharmacy_admin")


def require_verified():
    """
    Dependency that requires the user to be verified.
    Can be combined with require_role using multiple dependencies.
    """
    async def verification_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_verified:
            raise ForbiddenException("Email verification required")
        return current_user

    return verification_checker


def require_approved():
    """
    Dependency that requires the user to be admin-approved.
    Used for doctors, hospitals, pharmacies who need approval.
    """
    async def approval_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_admin_approved:
            raise ForbiddenException("Admin approval required")
        return current_user

    return approval_checker

